head.script:
scwin.gVar = {
    "cID" : ""
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제 (커스텀 id 가능 -> scwin.target1 레퍼런스로 제거)
    if (typeof scwin.target1 !== 'undefined' && scwin.target1) {
        scwin.target1.remove();
    }

    // 조건 설정 (con_ID 입력값 -> 빈 값이면 dynamicCreate 내부 규칙에 의한 ID 자동 부여)
    let cID = scwin.gVar["cID"];

    // getID 는 id 설정 유무에 따른 반환값 확인이 목적이므로 widgetContainer 를 직접 생성
    //  - createBasicWidgetContainer 는 빈 cID 를 target1 로 고정하므로 ID 미설정 케이스 검증에 부적합
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    let strTarget = '';
    strTarget += '<w2:widgetContainer ' + strNameSpace + ' mode="" cols="" style="width:300px;height:200px;"></w2:widgetContainer>';

    // base(common_M)가 objParent.scwin.target1 로 접근하므로 scwin.target1 에 생성된 widgetContainer 를 설정
    scwin.target1 = await $p.dynamicCreate(cID, "widgetContainer", strTarget, grp_comp);

    // 내용 확인용 Widget 1개 추가 (Widget 이 없으면 Container 내용이 비어 확인 불가)
    let addedWidgets = scwin.target1.addWidgets({
        id : "widget1",
        title : "위젯01",
        src : "/sample/common_link/widgetContainer_link_1.xml",
        scope : true,
        unitWidth : 1,
        unitHeight : 1
    });

    // 추가한 Widget 을 최대화 (maxConfig 미설정이므로 Container 크기만큼 확장)
    if (addedWidgets && addedWidgets[0]) {
        addedWidgets[0].setMaximized();
    }
}
